import type { BankQuestion } from "@/lib/bank";

/** Human Body and Biology Basics (General Science): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"sci-biology-1","question":"Which organelle is called the “powerhouse of the cell”?","options":["Ribosome","Nucleus","Mitochondria","Golgi body"],"answer":2,"explanation":"Mitochondria produce ATP through cellular respiration.","difficulty":"easy"},
  {"id":"sci-biology-2","question":"Insulin is secreted by the:","options":["Liver","Pancreas","Kidney","Thyroid"],"answer":1,"explanation":"The beta cells of the pancreas (islets of Langerhans) secrete insulin.","difficulty":"easy"},
  {"id":"sci-biology-3","question":"Which is the largest organ of the human body?","options":["Liver","Skin","Heart","Lungs"],"answer":1,"explanation":"The skin is the largest organ; the liver is the largest internal organ and gland.","difficulty":"easy"},
  {"id":"sci-biology-4","question":"Deficiency of Vitamin C causes:","options":["Rickets","Scurvy","Night blindness","Beriberi"],"answer":1,"explanation":"Scurvy (bleeding gums) is caused by a lack of Vitamin C.","difficulty":"moderate"},
  {"id":"sci-biology-5","question":"Which is the largest gland in the human body?","options":["Pancreas","Thyroid","Liver","Pituitary"],"answer":2,"explanation":"The liver is the largest gland; the skin is the largest organ.","difficulty":"moderate"},
  {"id":"sci-biology-6","question":"Which blood group is called the universal donor?","options":["A","B","AB","O"],"answer":3,"explanation":"Group O (negative) red cells carry no A or B antigens, so they can be given to any group.","difficulty":"moderate"},
  {"id":"sci-biology-7","question":"Which vitamin is made in the skin in sunlight?","options":["Vitamin A","Vitamin B12","Vitamin C","Vitamin D"],"answer":3,"explanation":"Ultraviolet light converts a cholesterol derivative in the skin into Vitamin D.","difficulty":"hard"},
  {"id":"sci-biology-8","question":"A normal human cell has how many pairs of chromosomes?","options":["22","23","44","46"],"answer":1,"explanation":"Humans have 46 chromosomes arranged in 23 pairs.","difficulty":"hard"},
  {"id":"sci-biology-9","question":"Red blood cells are produced in the:","options":["Liver","Bone marrow","Spleen","Heart"],"answer":1,"explanation":"Red bone marrow produces red blood cells; the spleen destroys old ones.","difficulty":"hard"},
  {"id":"sci-biology-10","question":"Which part of the brain controls balance and coordination?","options":["Cerebrum","Cerebellum","Medulla oblongata","Hypothalamus"],"answer":1,"explanation":"The cerebellum coordinates voluntary movement and balance.","difficulty":"very-hard"},
  {"id":"sci-biology-11","question":"The structural and functional unit of the kidney is the:","options":["Neuron","Nephron","Alveolus","Villus"],"answer":1,"explanation":"Each kidney has about a million nephrons that filter blood to form urine.","difficulty":"very-hard"},
  {"id":"sci-biology-12","question":"The average lifespan of a human red blood cell is about:","options":["12 days","60 days","120 days","365 days"],"answer":2,"explanation":"Red blood cells live about 120 days before being broken down in the spleen and liver.","difficulty":"very-hard"},
  {"id":"sci-biology-13","question":"The largest organ of the human body is the:","options":["Liver","Skin","Lungs","Brain"],"answer":1,"explanation":"Skin is the largest organ; the liver is the largest internal organ.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"sci-biology-14","question":"Which blood group is the “universal donor”?","options":["A","B","AB","O negative"],"answer":3,"explanation":"O negative has no A, B or Rh antigens, so it can be given to anyone.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-15","question":"Which vitamin deficiency causes scurvy?","options":["Vitamin A","Vitamin B12","Vitamin C","Vitamin D"],"answer":2,"explanation":"Scurvy comes from a lack of vitamin C (ascorbic acid).","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"sci-biology-16","question":"Insulin is produced by which cells of the pancreas?","options":["Alpha cells","Beta cells","Delta cells","Kupffer cells"],"answer":1,"explanation":"Beta cells of the islets of Langerhans secrete insulin; alpha cells secrete glucagon.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-17","question":"The normal human body has how many pairs of chromosomes?","options":["22","23","24","46"],"answer":1,"explanation":"Humans have 23 pairs (46 chromosomes), including one pair of sex chromosomes.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-18","question":"Which part of the human eye controls the amount of light entering it?","options":["Cornea","Iris","Retina","Lens"],"answer":1,"explanation":"The iris adjusts the size of the pupil; the retina forms the image.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"sci-biology-19","question":"Which vessel carries oxygenated blood from the lungs to the heart?","options":["Pulmonary artery","Pulmonary vein","Aorta","Vena cava"],"answer":1,"explanation":"Pulmonary veins are the only veins that carry oxygenated blood.","difficulty":"hard"},
  {"id":"sci-biology-20","question":"Which of these is NOT a function of the liver?","options":["Making bile","Storing glycogen","Detoxifying drugs","Producing insulin"],"answer":3,"explanation":"Insulin comes from the beta cells of the pancreas.","difficulty":"hard"},
  {"id":"sci-biology-21","question":"Consider: 1. Mature mammalian red blood cells have no nucleus. 2. Haemoglobin contains iron. 3. Platelets help blood to clot. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct.","difficulty":"very-hard"},
  {"id":"sci-biology-22","question":"A colour-blind man marries a woman with normal vision who is not a carrier. What is the chance that their son is colour-blind?","options":["0%","25%","50%","100%"],"answer":0,"explanation":"Colour blindness is X-linked; a son gets his X from his mother, who has two normal X chromosomes.","difficulty":"very-hard"},
  {"id":"sci-biology-23","question":"How many of these statements are correct? I. Vitamin K helps blood clot. II. Rickets is caused by a lack of vitamin D. III. Night blindness is caused by a lack of vitamin B1. IV. Beriberi is caused by a lack of vitamin B1.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Night blindness comes from a lack of vitamin A.","difficulty":"very-hard"},
  {"id":"sci-biology-24","question":"How many of these statements are correct? I. Mitochondria are called the powerhouse of the cell. II. Ribosomes are the site of protein synthesis. III. Plant cells have no cell wall.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Plant cells have a cellulose cell wall.","difficulty":"very-hard"},
  {"id":"sci-biology-25","question":"How many of these statements are correct? I. Mature red blood cells in mammals have no nucleus. II. Platelets help blood to clot. III. Lymphocytes are a type of red blood cell.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Lymphocytes are white blood cells.","difficulty":"very-hard"},
  {"id":"sci-biology-26","question":"Which vitamin is made by bacteria in the human large intestine?","options":["Vitamin A","Vitamin C","Vitamin K","Vitamin D"],"answer":2,"explanation":"Gut bacteria make vitamin K. Vitamin D is made in the skin in sunlight, not by bacteria.","difficulty":"very-hard"},
  {"id":"sci-biology-27","question":"A father has blood group AB and a mother has group O. Which blood groups can their children have?","options":["A or B only","AB or O only","A, B, AB or O","O only"],"answer":0,"explanation":"The father passes A or B, the mother always passes O: children are AO (group A) or BO (group B).","difficulty":"very-hard"},
  {"id":"sci-biology-28","question":"Which pair of hormone and the gland that secretes it is NOT correctly matched?","options":["Insulin – pancreas","Thyroxine – thyroid","Adrenaline – adrenal gland","Oxytocin – thyroid"],"answer":3,"explanation":"Oxytocin is released by the posterior pituitary. The thyroid secretes thyroxine and calcitonin.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-29","question":"In pea plants tallness (T) is dominant over dwarfness (t). Two heterozygous tall plants are crossed and 400 offspring are obtained. How many are expected to be tall but heterozygous?","options":["200","300","100","400"],"answer":0,"explanation":"Tt × Tt gives TT : Tt : tt = 1 : 2 : 1. Heterozygous tall (Tt) is half the offspring: 200. (300 would be all tall plants.)","difficulty":"very-hard","source":"SSC CGL · CTET"},
  {"id":"sci-biology-30","question":"The normal body temperature of a healthy human being is about:","options":["35 °C","37 °C","39 °C","42 °C"],"answer":1,"explanation":"Normal core temperature is about 37 °C (98.6 °F); 39 °C and above indicates fever.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-31","question":"Which blood cells defend the body against infection?","options":["Red blood cells","Platelets","White blood cells","Plasma cells only"],"answer":2,"explanation":"White blood cells (leucocytes) fight infection; red cells carry oxygen and platelets help clotting.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-32","question":"The pigment responsible for the colour of human skin is:","options":["Haemoglobin","Melanin","Carotene","Keratin"],"answer":1,"explanation":"Melanin, produced by melanocytes, gives skin, hair and eyes their colour and protects against ultraviolet light.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-33","question":"The number of bones in an adult human body is:","options":["196","206","212","300"],"answer":1,"explanation":"An adult has 206 bones; a newborn has about 300 bony elements, many of which fuse during growth.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-34","question":"The smallest bone in the human body is the:","options":["Stapes","Femur","Patella","Malleus"],"answer":0,"explanation":"The stapes (stirrup) in the middle ear is the smallest bone; the femur (thigh bone) is the longest and strongest.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-35","question":"The hormone that prepares the body for a “fight or flight” response is:","options":["Insulin","Thyroxine","Adrenaline","Oestrogen"],"answer":2,"explanation":"Adrenaline (epinephrine) from the adrenal medulla raises heart rate, blood pressure and blood sugar during stress.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-36","question":"Which organ removes urea from the blood?","options":["Liver","Kidney","Spleen","Pancreas"],"answer":1,"explanation":"Urea is made in the liver but filtered out of the blood by the kidneys and excreted in urine.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-37","question":"The normal blood pressure of a healthy adult is about:","options":["80/120 mm Hg","120/80 mm Hg","140/90 mm Hg","100/100 mm Hg"],"answer":1,"explanation":"Normal pressure is about 120 mm Hg systolic over 80 mm Hg diastolic; 140/90 is the threshold for hypertension.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-38","question":"The human heart has how many chambers?","options":["Two","Three","Four","Five"],"answer":2,"explanation":"The human heart has four chambers: two atria and two ventricles, keeping oxygenated and deoxygenated blood separate.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-39","question":"Bile is produced in the liver but stored in the:","options":["Pancreas","Gall bladder","Duodenum","Spleen"],"answer":1,"explanation":"Bile is secreted by liver cells and concentrated and stored in the gall bladder, which releases it into the duodenum to emulsify fats.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-40","question":"Starch digestion begins in the mouth because saliva contains the enzyme:","options":["Pepsin","Lipase","Ptyalin","Trypsin"],"answer":2,"explanation":"Salivary amylase (ptyalin) converts starch into maltose in the mouth; pepsin and trypsin digest proteins.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-41","question":"Body temperature, hunger and thirst are regulated by which part of the brain?","options":["Cerebellum","Medulla oblongata","Hypothalamus","Cerebrum"],"answer":2,"explanation":"The hypothalamus is the body’s thermostat and also controls hunger, thirst, sleep and the pituitary gland.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-42","question":"The total volume of blood in an average adult human is about:","options":["2 litres","5 litres","8 litres","10 litres"],"answer":1,"explanation":"An adult has about 5 litres of blood, roughly 7–8% of body weight.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-43","question":"Pernicious anaemia is caused by the deficiency of:","options":["Vitamin B1","Vitamin B12","Vitamin C","Vitamin K"],"answer":1,"explanation":"Vitamin B12 (cobalamin) is needed to make red blood cells; its deficiency, often due to poor absorption, causes pernicious anaemia.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-44","question":"The exchange of oxygen and carbon dioxide in the lungs takes place in the:","options":["Bronchi","Trachea","Alveoli","Pleura"],"answer":2,"explanation":"The alveoli are tiny thin-walled air sacs surrounded by capillaries where gases diffuse between air and blood.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-45","question":"Dengue is transmitted by the bite of which mosquito?","options":["Female Anopheles","Female Aedes aegypti","Female Culex","Male Aedes"],"answer":1,"explanation":"Aedes aegypti (a day-biting mosquito) spreads dengue, chikungunya and Zika; Anopheles spreads malaria and Culex filariasis.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-46","question":"The BCG vaccine gives protection against:","options":["Polio","Tetanus","Tuberculosis","Measles"],"answer":2,"explanation":"BCG (Bacillus Calmette–Guérin) is given at birth in India to protect against tuberculosis.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-47","question":"The longest cell in the human body is the:","options":["Muscle cell","Nerve cell","Red blood cell","Bone cell"],"answer":1,"explanation":"A single neuron can be over a metre long, running from the spinal cord to the toes; the ovum is the largest cell by volume.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-48","question":"How many of these statements are correct? I. An adult has 206 bones while a newborn has about 300. II. The resting human heart beats about 72 times a minute. III. An adult has 32 permanent teeth. IV. There are 31 pairs of spinal nerves.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct standard numbers; the trap is 12 pairs of cranial nerves, which is a different count from the 31 pairs of spinal nerves.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-49","question":"Assertion (A): Vaccination provides active immunity. Reason (R): A vaccine stimulates the body to make its own antibodies and memory cells.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Immunity produced by the body’s own response is active; passive immunity comes from ready-made antibodies such as antiserum or a mother’s milk.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-50","question":"Match the vitamin with its chemical name: 1. Vitamin A 2. Vitamin B1 3. Vitamin C 4. Vitamin D; a. Ascorbic acid b. Calciferol c. Retinol d. Thiamine","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-b, 2-d, 3-a, 4-c"],"answer":0,"explanation":"Vitamin A is retinol, B1 thiamine, C ascorbic acid and D calciferol.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-51","question":"A man of blood group A (genotype IᴬI°) marries a woman of blood group B (genotype IᴮI°). Which blood groups are possible among their children?","options":["Only A and B","Only AB","A, B, AB and O","Only AB and O"],"answer":2,"explanation":"The gametes Iᴬ or I° combine with Iᴮ or I°, giving IᴬIᴮ (AB), IᴬI° (A), IᴮI° (B) and I°I° (O), each with probability 1/4.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-52","question":"Which of the following is NOT a function of the kidney?","options":["Regulating the water balance of the body","Producing the hormone erythropoietin","Producing bile","Removing urea from the blood"],"answer":2,"explanation":"Bile is made by the liver; the kidney excretes nitrogenous waste, controls water and salt balance and secretes erythropoietin, which stimulates red-cell production.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-53","question":"How many of these statements about blood are correct? I. Blood group O has no A or B antigens on the red cells. II. Blood group AB has no anti-A or anti-B antibodies in its plasma. III. An Rh-negative mother carrying an Rh-positive foetus can face erythroblastosis foetalis. IV. Haemoglobin is found in white blood cells.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (which is why O is the universal donor and AB the universal recipient). IV is wrong: haemoglobin is in red blood cells.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-54","question":"Match the disease with its causative organism: 1. Tuberculosis 2. Malaria 3. Rabies 4. Ringworm; a. Virus b. Fungus c. Bacterium d. Protozoan","options":["1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"TB is caused by the bacterium Mycobacterium tuberculosis, malaria by the protozoan Plasmodium, rabies by a virus and ringworm by a fungus.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-55","question":"The correct sequence in which these enzymes act on proteins in the human digestive tract is:","options":["Trypsin → pepsin → peptidases","Pepsin → trypsin → peptidases","Peptidases → pepsin → trypsin","Pepsin → peptidases → trypsin"],"answer":1,"explanation":"Pepsin in the stomach starts protein digestion, pancreatic trypsin continues it in the small intestine, and intestinal peptidases finish breaking peptides into amino acids.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-56","question":"Assertion (A): Insulin and glucagon have opposite effects on blood sugar. Reason (R): Both insulin and glucagon are secreted by the pancreas.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Insulin (beta cells) lowers and glucagon (alpha cells) raises blood glucose; both are pancreatic, but sharing a gland is not the reason their actions are opposite.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-57","question":"How many of these statements about the nervous system are correct? I. The cerebrum is the largest part of the brain. II. The medulla oblongata controls heartbeat and breathing. III. Reflex actions are controlled by the cerebellum. IV. Humans have 12 pairs of cranial nerves.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: simple reflex arcs are handled by the spinal cord; the cerebellum coordinates balance and movement.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-58","question":"Two pea plants heterozygous for both seed colour and seed shape (YyRr × YyRr) produce 1,600 offspring. The expected number showing both recessive traits is:","options":["100","300","400","900"],"answer":0,"explanation":"The dihybrid ratio is 9:3:3:1, so double recessives (yyrr) are 1/16 of 1,600 = 100.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-59","question":"Which pair of hormone and disorder is NOT correctly matched?","options":["Thyroxine deficiency – goitre","Insulin deficiency – diabetes mellitus","ADH deficiency – diabetes insipidus","Growth hormone excess in adults – cretinism"],"answer":3,"explanation":"Excess growth hormone in adults causes acromegaly (and gigantism in children); cretinism results from thyroxine deficiency in infancy.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id": "sci-biology-60", "question": "Blood vessels that carry blood away from the heart to the body are called:", "options": ["Veins", "Arteries", "Capillaries", "Venules"], "answer": 1, "explanation": "Arteries carry blood away from the heart, veins bring it back, and capillaries link the two in the tissues.", "difficulty": "easy", "source": "SSC GD · RRB Group D"},
  {"id": "sci-biology-61", "question": "The basic functional unit of heredity is the:", "options": ["Cell", "Ribosome", "Nucleus", "Gene"], "answer": 3, "explanation": "A gene is a segment of DNA that carries the information for a trait and is passed from parents to offspring.", "difficulty": "easy", "source": "SSC CHSL · RRB Group D"},
  {"id": "sci-biology-62", "question": "Most of the digested food is absorbed in the:", "options": ["Stomach", "Large intestine", "Small intestine", "Oesophagus"], "answer": 2, "explanation": "Finger-like villi lining the small intestine give a huge surface for absorption. The large intestine mainly absorbs water and salts.", "difficulty": "moderate", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-biology-63", "question": "Goitre, a swelling of the thyroid gland, is caused by a deficiency of:", "options": ["Iodine", "Iron", "Calcium", "Zinc"], "answer": 0, "explanation": "Iodine is needed to make thyroxine; without it the thyroid enlarges. This is why salt is iodised in India.", "difficulty": "moderate", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-biology-64", "question": "Photosynthesis in a green plant cell takes place in the:", "options": ["Mitochondria", "Chloroplasts", "Ribosomes", "Golgi bodies"], "answer": 1, "explanation": "Chloroplasts contain chlorophyll, which traps light energy to make glucose from carbon dioxide and water. Mitochondria carry out respiration.", "difficulty": "moderate", "source": "SSC CHSL · RRB NTPC"},
  {"id": "sci-biology-65", "question": "Which of the following diseases is caused by a virus?", "options": ["Typhoid", "Cholera", "Tuberculosis", "Polio"], "answer": 3, "explanation": "Polio is caused by the poliovirus. Typhoid, cholera and tuberculosis are bacterial diseases.", "difficulty": "moderate", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-biology-66", "question": "Iron is an essential component of:", "options": ["Insulin", "Haemoglobin", "Chlorophyll", "Thyroxine"], "answer": 1, "explanation": "Each haem group of haemoglobin contains an iron atom that binds oxygen. Chlorophyll contains magnesium, a common trap, and thyroxine contains iodine.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-67", "question": "The cells of the retina responsible for colour vision and vision in bright light are:", "options": ["Rods", "Cones", "Bipolar cells", "Ganglion cells"], "answer": 1, "explanation": "Cones work in bright light and detect colour; rods contain rhodopsin and work in dim light but cannot detect colour.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-68", "question": "Which enzyme of the pancreatic juice digests fats?", "options": ["Amylase", "Trypsin", "Lipase", "Pepsin"], "answer": 2, "explanation": "Pancreatic lipase breaks emulsified fats into fatty acids and glycerol. Amylase acts on starch, trypsin on proteins, and pepsin is a stomach enzyme.", "difficulty": "hard", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-biology-69", "question": "Haemophilia is best described as:", "options": ["A Y-linked disorder in which red cells become sickle-shaped", "An X-linked recessive disorder in which blood does not clot properly", "A vitamin deficiency disease affecting the bones", "An autosomal dominant disorder causing colour blindness"], "answer": 1, "explanation": "Haemophilia is an X-linked recessive condition, so it is far commoner in males; a minor cut can bleed for a long time.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-70", "question": "The part of the human inner ear that helps maintain the balance of the body is the:", "options": ["Cochlea", "Semicircular canals", "Tympanum", "Ear ossicles"], "answer": 1, "explanation": "The fluid-filled semicircular canals (with the vestibule) sense head movement and position. The cochlea is concerned with hearing.", "difficulty": "hard", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-biology-71", "question": "In humans, the sex of a child is determined by:", "options": ["The X chromosome from the mother", "The chromosome (X or Y) contributed by the father’s sperm", "The nutrition of the mother during pregnancy", "The number of autosomes in the egg"], "answer": 1, "explanation": "Every egg carries an X chromosome; a sperm carries X or Y. An X sperm gives a girl (XX) and a Y sperm a boy (XY).", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-72", "question": "Antibodies in the human body are produced by:", "options": ["T-lymphocytes", "Platelets", "Red blood cells", "B-lymphocytes (plasma cells)"], "answer": 3, "explanation": "B-lymphocytes turn into plasma cells that secrete antibodies (humoral immunity). T-lymphocytes give cell-mediated immunity and do not make antibodies.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-73", "question": "The cell organelle that modifies, sorts and packages proteins for secretion is the:", "options": ["Endoplasmic reticulum", "Golgi apparatus", "Lysosome", "Nucleolus"], "answer": 1, "explanation": "Proteins made on the rough ER travel to the Golgi apparatus, which modifies and packs them into vesicles for secretion.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-74", "question": "How many of these statements about cells are correct? I. Plant cells contain plastids. II. Animal cells usually have centrioles. III. Ribosomes are bounded by a membrane. IV. Mitochondria have their own DNA.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. Ribosomes have no membrane; they are made of RNA and protein, which is why they are found even in bacteria.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-75", "question": "Assertion (A): Arteries have thicker and more elastic walls than veins. Reason (R): Arteries carry blood away from the heart under high pressure.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The thick muscular, elastic walls let arteries withstand and smooth out the high pressure of each heartbeat. R explains A.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-76", "question": "Assertion (A): The pulmonary artery carries oxygenated blood. Reason (R): Arteries carry blood away from the heart.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: the pulmonary artery carries deoxygenated blood from the right ventricle to the lungs. R is true, which is why it is still called an artery.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-77", "question": "Match the disease with its vector: 1. Malaria 2. Dengue 3. Sleeping sickness 4. Plague; a. Rat flea b. Tsetse fly c. Female Anopheles mosquito d. Aedes mosquito", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-a, 4-b", "1-c, 2-b, 3-d, 4-a"], "answer": 0, "explanation": "Anopheles spreads malaria, Aedes spreads dengue, the tsetse fly spreads African sleeping sickness and the rat flea spreads plague.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-78", "question": "A tall pea plant is crossed with a dwarf plant (tt), and half the offspring are tall and half dwarf. The genotype of the tall parent is:", "options": ["TT", "Tt", "tt", "It cannot be determined"], "answer": 1, "explanation": "This is a test cross. Tt × tt gives Tt and tt in a 1 : 1 ratio. If the tall parent were TT, every offspring would be tall.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-79", "question": "A woman who is a carrier of colour blindness marries a man with normal vision. What is expected among their children?", "options": ["50% of the sons colour-blind and none of the daughters", "25% of the sons and 25% of the daughters colour-blind", "All the sons colour-blind and none of the daughters", "No sons colour-blind and 50% of the daughters colour-blind"], "answer": 0, "explanation": "Mother XᶜX × father XY. Sons get the X from the mother, so half are XᶜY (colour-blind). Daughters get the father’s normal X, so none are colour-blind, though half are carriers.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-80", "question": "Which pair of digestive enzyme and the food it acts on is NOT correctly matched?", "options": ["Pepsin – proteins", "Salivary amylase – starch", "Trypsin – starch", "Lipase – fats"], "answer": 2, "explanation": "Trypsin, from the pancreas, digests proteins. Starch is digested by salivary and pancreatic amylase.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-81", "question": "How many of these statements are correct? I. Anaerobic respiration in human muscles produces lactic acid. II. Anaerobic respiration in yeast produces ethanol and carbon dioxide. III. Glycolysis requires oxygen. IV. The breakdown of glucose to pyruvate takes place in the mitochondria.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Glycolysis needs no oxygen and occurs in the cytoplasm; only the later breakdown of pyruvate in aerobic respiration takes place in the mitochondria.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-82", "question": "Arrange these discoveries in chronological order: 1. Discovery of penicillin 2. Discovery of the cell 3. Double-helix model of DNA 4. First smallpox vaccine", "options": ["2, 4, 3, 1", "4, 2, 1, 3", "2, 1, 4, 3", "2, 4, 1, 3"], "answer": 3, "explanation": "Robert Hooke saw cells in 1665, Edward Jenner made the smallpox vaccine in 1796, Alexander Fleming found penicillin in 1928, and Watson and Crick proposed the double helix in 1953.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-83", "question": "How many of these statements about deficiency diseases are correct? I. Kwashiorkor is caused mainly by a lack of protein. II. Marasmus results from a deficiency of both protein and calories. III. Lack of iron causes anaemia. IV. Children with kwashiorkor often show swelling (oedema) of the body.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The swollen belly and limbs in kwashiorkor distinguish it from marasmus, where the child is severely wasted.", "difficulty": "very-hard", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-biology-84", "question": "A person’s heart beats 72 times a minute and pumps 70 mL of blood per beat from the left ventricle. The cardiac output is about:", "options": ["504 mL per minute", "5.04 litres per minute", "50.4 litres per minute", "1.4 litres per minute"], "answer": 1, "explanation": "Cardiac output = heart rate × stroke volume = 72 × 70 mL = 5,040 mL ≈ 5.04 litres per minute, roughly the whole blood volume every minute.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-85", "question": "Plants lose water vapour mainly through tiny pores on their leaves called:", "options": ["Xylem vessels", "Root hairs", "Lenticels", "Stomata"], "answer": 3, "explanation": "Transpiration takes place mostly through stomata, each opened and closed by a pair of guard cells. Lenticels are pores in woody stems and lose only a little water.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "sci-biology-86", "question": "The scientific name of modern human beings is:", "options": ["Homo erectus", "Homo sapiens", "Pan troglodytes", "Homo habilis"], "answer": 1, "explanation": "In binomial naming the genus comes first (Homo) and the species second (sapiens). Homo erectus and Homo habilis are extinct human species, and Pan troglodytes is the chimpanzee.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "sci-biology-87", "question": "The branch of biology that studies the relationship between living organisms and their environment is:", "options": ["Ethology", "Ecology", "Taxonomy", "Physiology"], "answer": 1, "explanation": "Ecology deals with interactions among organisms and with their surroundings. Ethology is the study of animal behaviour and taxonomy the science of classification.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "sci-biology-88", "question": "Which plant hormone is used to ripen fruits artificially?", "options": ["Gibberellin", "Ethylene", "Cytokinin", "Auxin"], "answer": 1, "explanation": "Ethylene, a gaseous hormone, speeds up the ripening of fruits such as bananas and mangoes. Auxin promotes cell elongation and cytokinin cell division.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-89", "question": "The shoulder joint and the hip joint are examples of:", "options": ["Gliding joints", "Hinge joints", "Ball-and-socket joints", "Pivot joints"], "answer": 2, "explanation": "The rounded head of one bone fits into a cup of the other, allowing movement in all directions. The knee and elbow are hinge joints, and the joint between the first two neck vertebrae is a pivot joint.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-90", "question": "Lymph differs from blood mainly because it has no:", "options": ["Red blood cells", "White blood cells", "Proteins", "Water"], "answer": 0, "explanation": "Lymph is tissue fluid collected by lymph vessels; it contains lymphocytes and some protein but no red blood cells, which is why it is colourless.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-91", "question": "In a flowering plant, water and minerals are carried from the roots to the leaves by the:", "options": ["Cambium", "Cortex", "Phloem", "Xylem"], "answer": 3, "explanation": "Xylem carries water and dissolved minerals upward, pulled mainly by transpiration. Phloem carries food made in the leaves to other parts in both directions.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "sci-biology-92", "question": "Insectivorous plants such as the pitcher plant trap insects mainly to obtain:", "options": ["Water", "Oxygen", "Nitrogen", "Carbohydrates"], "answer": 2, "explanation": "These plants grow in nitrogen-poor soils and digest insects to get nitrogen compounds. They still make their own carbohydrates by photosynthesis, since they have green leaves.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-93", "question": "The dark reactions (Calvin cycle) of photosynthesis take place in the:", "options": ["Thylakoid membranes", "Stroma of the chloroplast", "Mitochondria", "Cytoplasm"], "answer": 1, "explanation": "Light reactions occur on the thylakoids and make ATP and NADPH; these are used in the stroma, the fluid around the thylakoids, to fix CO₂ into sugar.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-94", "question": "In human males, sperms are produced in the:", "options": ["Epididymis", "Seminiferous tubules of the testes", "Vas deferens", "Prostate gland"], "answer": 1, "explanation": "Sperms form in the seminiferous tubules and then mature and are stored in the epididymis. The vas deferens carries them, and the prostate adds fluid to semen.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-95", "question": "In a food chain, producers fix 10,000 J of energy. Following the ten per cent law, the energy available to the tertiary consumers is:", "options": ["1 J", "10 J", "100 J", "1,000 J"], "answer": 1, "explanation": "About 10% passes to each higher level: primary consumers get 1,000 J, secondary 100 J and tertiary 10 J. Stopping one level early gives 100 J.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-96", "question": "Which plant hormone makes stomata close when a plant faces water shortage?", "options": ["Gibberellin", "Abscisic acid", "Cytokinin", "Auxin"], "answer": 1, "explanation": "Abscisic acid (ABA) is the ‘stress hormone’: it builds up during drought and closes stomata to save water. It also promotes dormancy, while gibberellins break it.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-97", "question": "Blood rich in digested food is carried from the intestines to the liver by the:", "options": ["Hepatic portal vein", "Inferior vena cava", "Hepatic artery", "Hepatic vein"], "answer": 0, "explanation": "The hepatic portal vein brings nutrient-rich blood from the gut to the liver for processing. The hepatic artery brings oxygenated blood, and the hepatic vein drains the liver into the vena cava.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-98", "question": "Human insulin made by recombinant DNA technology, first marketed in 1982, was produced using:", "options": ["The bacterium Escherichia coli", "Tobacco plants", "Pancreas of pigs", "Yeast extract from bread"], "answer": 0, "explanation": "The human insulin gene was put into E. coli, which made the hormone in bulk (Humulin). Before that, diabetics used insulin taken from the pancreas of pigs and cattle.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-99", "question": "Which of the following is NOT a fungus?", "options": ["Yeast", "Penicillium", "Mushroom", "Euglena"], "answer": 3, "explanation": "Euglena is a single-celled protist with chloroplasts that can also feed like an animal. Yeast, mushrooms and the mould Penicillium are all fungi.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-100", "question": "Most of the carbon dioxide in human blood is transported as:", "options": ["Dissolved CO₂ in plasma", "Bicarbonate ions in plasma", "Carbaminohaemoglobin", "Carbonic acid inside platelets"], "answer": 1, "explanation": "About 70% travels as bicarbonate, formed inside red cells with the enzyme carbonic anhydrase; about 20–25% is bound to haemoglobin and only about 7% is dissolved.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-101", "question": "The metal ion at the centre of a chlorophyll molecule and the one at the centre of the haem in haemoglobin are respectively:", "options": ["Magnesium and copper", "Magnesium and iron", "Iron and magnesium", "Copper and iron"], "answer": 1, "explanation": "Chlorophyll has a magnesium ion in its porphyrin ring and haem has an iron ion. Copper is found in haemocyanin, the blue oxygen carrier of some molluscs and arthropods.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-102", "question": "In the nephron, ultrafiltration of blood takes place in the:", "options": ["Glomerulus and Bowman’s capsule", "Distal convoluted tubule", "Collecting duct", "Loop of Henle"], "answer": 0, "explanation": "High pressure in the glomerular capillaries forces water and small solutes into Bowman’s capsule. Reabsorption of water and salts happens later along the tubule and collecting duct.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-103", "question": "How many of these statements about photosynthesis are correct? I. The oxygen released comes from water, not from carbon dioxide. II. The light reactions take place in the thylakoid membranes. III. Making glucose in the Calvin cycle uses ATP and NADPH from the light reactions. IV. Photosynthesis is an exothermic process.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct; experiments with heavy-oxygen water showed that O₂ comes from splitting water. IV is wrong: photosynthesis stores light energy in sugar, so it is endothermic.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-104", "question": "Match the plant hormone with its main effect: 1. Auxin 2. Gibberellin 3. Cytokinin 4. Ethylene; a. Ripening of fruits b. Cell division and delay of leaf ageing c. Stem elongation and bolting d. Apical dominance and bending towards light", "options": ["1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a"], "answer": 1, "explanation": "Auxin causes phototropism and apical dominance, gibberellins lengthen stems and cause bolting, cytokinins promote cell division and delay senescence, and ethylene ripens fruit.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-105", "question": "Assertion (A): Birds and most reptiles excrete nitrogenous waste mainly as uric acid. Reason (R): Uric acid is nearly insoluble and can be removed with very little loss of water.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Ammonia needs much water to flush out, urea less, and uric acid the least because it is passed as a paste. Being uricotelic saves water, which suits flying birds and egg-laying reptiles, so R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-106", "question": "How many of these statements about energy flow in ecosystems are correct? I. Energy flows through an ecosystem in one direction only. II. The pyramid of energy is always upright. III. The pyramid of biomass in a pond ecosystem is usually inverted. IV. Only about 10% of the energy at one trophic level passes to the next.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Energy is lost as heat at every level, so it cannot cycle and its pyramid is never inverted; in a pond, the small biomass of fast-reproducing phytoplankton supports a larger biomass of consumers.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-107", "question": "Arrange in chronological order: 1. Rediscovery of Mendel’s laws 2. Publication of Darwin’s ‘On the Origin of Species’ 3. Birth of the first ‘test-tube baby’ 4. Mendel presents his experiments on pea plants", "options": ["4, 2, 1, 3", "2, 1, 4, 3", "2, 4, 1, 3", "2, 4, 3, 1"], "answer": 2, "explanation": "Darwin’s book appeared in 1859, Mendel published in 1865–66, his work was rediscovered by de Vries, Correns and Tschermak in 1900, and Louise Brown, the first IVF baby, was born in 1978.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-108", "question": "In snapdragon, red-flowered and white-flowered plants show incomplete dominance and give pink-flowered plants in F₁. If 200 F₂ plants are raised from selfing the F₁, how many are expected to have pink flowers?", "options": ["100", "150", "200", "50"], "answer": 0, "explanation": "With incomplete dominance the F₂ ratio is 1 red : 2 pink : 1 white, so half the plants, 100 of 200, are pink (heterozygous). Using the 3 : 1 Mendelian ratio gives the trap 150.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-109", "question": "Which of the following is NOT secreted by the human stomach?", "options": ["Mucus", "Trypsinogen", "Hydrochloric acid", "Pepsinogen"], "answer": 1, "explanation": "Trypsinogen is secreted by the pancreas and activated to trypsin in the small intestine. The gastric glands secrete pepsinogen, hydrochloric acid, mucus and, in infants, rennin.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-110", "question": "Assertion (A): In many desert plants the leaves are reduced to spines. Reason (R): Reducing the leaf surface cuts down water loss by transpiration.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Smaller leaf area means fewer stomata and less water lost, which is vital where water is scarce; photosynthesis is then often taken over by a green, fleshy stem, as in cactus. So R explains A.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-111", "question": "Match the gland with a hormone it secretes: 1. Thymus 2. Pineal gland 3. Adrenal cortex 4. Parathyroid; a. Parathormone b. Cortisol c. Melatonin d. Thymosin", "options": ["1-b, 2-c, 3-d, 4-a", "1-d, 2-c, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a"], "answer": 1, "explanation": "The thymus secretes thymosin (T-cell maturation), the pineal gland melatonin (sleep–wake rhythm), the adrenal cortex cortisol (stress, glucose metabolism) and the parathyroids parathormone (raises blood calcium).", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-112", "question": "A person breathes 12 times a minute with a tidal volume of 500 mL, of which 150 mL stays in the anatomical dead space (air passages). The volume of fresh air reaching the alveoli each minute is:", "options": ["6.0 litres", "1.8 litres", "4.2 litres", "7.8 litres"], "answer": 2, "explanation": "Air reaching the alveoli per breath = 500 − 150 = 350 mL; per minute = 350 × 12 = 4,200 mL = 4.2 L. The total pulmonary ventilation, 500 × 12 = 6 L, includes the dead-space air that never takes part in gas exchange.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-113", "question": "How many of these statements about immunity are correct? I. Colostrum gives the newborn passive immunity through IgA antibodies. II. Antibodies are proteins. III. HIV mainly destroys B-lymphocytes. IV. An injection of antivenom gives active immunity against snake venom.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. HIV attacks helper T-lymphocytes (CD4 cells), and antivenom supplies ready-made antibodies, which is passive, short-lived immunity.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-biology-114", "question": "How many of these statements about the human skeletal system are correct? I. The femur is the longest bone in the body. II. The knee is a hinge joint. III. Humans have 12 pairs of ribs. IV. Ligaments join muscles to bones.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: tendons join muscles to bones, while ligaments join bone to bone at joints.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-115", "question": "Which blood components help the blood to clot at a cut?", "options": ["Red blood cells", "Platelets", "White blood cells", "Plasma proteins only, without any cells"], "answer": 1, "explanation": "Platelets gather at the injury and release factors that, with plasma proteins such as fibrinogen, form a clot. Red cells carry oxygen and white cells fight infection.", "difficulty": "easy", "source": "SSC CHSL · RRB Group D"},
  {"id": "sci-biology-116", "question": "The kidneys are part of which organ system of the human body?", "options": ["Digestive system", "Respiratory system", "Excretory system", "Nervous system"], "answer": 2, "explanation": "The kidneys filter blood and remove urea and excess salts as urine, together with the ureters, bladder and urethra.", "difficulty": "easy", "source": "SSC CHSL · RRB Group D"},
  {"id": "sci-biology-117", "question": "Which class of nutrients is the body's main and quickest source of energy?", "options": ["Carbohydrates", "Vitamins", "Minerals", "Proteins"], "answer": 0, "explanation": "Carbohydrates such as starch and sugars are broken down to glucose for energy. Proteins mainly build and repair tissues; vitamins and minerals regulate body processes.", "difficulty": "easy", "source": "SSC CHSL · RRB Group D"},
  {"id": "sci-biology-118", "question": "The basic structural and functional unit of the nervous system is the:", "options": ["Nephron", "Alveolus", "Sarcomere", "Neuron"], "answer": 3, "explanation": "Neurons carry electrical and chemical signals. The nephron is the unit of the kidney, the alveolus of the lung and the sarcomere of muscle.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-119", "question": "In the human eye, the image of an object is formed on the:", "options": ["Retina", "Cornea", "Iris", "Lens"], "answer": 0, "explanation": "The cornea and lens focus light onto the retina, whose rods and cones convert it into nerve signals carried by the optic nerve to the brain.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-120", "question": "Which gland is often called the “master gland” because its hormones control several other endocrine glands?", "options": ["Thyroid", "Pituitary", "Adrenal", "Pancreas"], "answer": 1, "explanation": "The pituitary, at the base of the brain, releases hormones that regulate the thyroid, adrenal cortex and gonads; it is itself controlled by the hypothalamus.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-121", "question": "The largest part of the human brain, responsible for thinking, memory and voluntary actions, is the:", "options": ["Cerebellum", "Medulla oblongata", "Cerebrum", "Pons"], "answer": 2, "explanation": "The cerebrum forms most of the brain. The cerebellum coordinates balance and the medulla controls involuntary actions such as breathing and heartbeat.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-122", "question": "A person with which blood group can, in principle, receive red cells from donors of any ABO group?", "options": ["O", "A", "B", "AB"], "answer": 3, "explanation": "Group AB plasma has neither anti-A nor anti-B antibodies, so AB is the universal recipient. Group O, whose red cells carry no A or B antigen, is the universal donor.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-123", "question": "Erythroblastosis fetalis, a serious condition of the newborn, can occur when:", "options": ["An Rh-negative mother, sensitised by an earlier pregnancy, carries an Rh-positive foetus", "An Rh-positive mother carries an Rh-negative foetus", "Both parents are Rh-negative", "The mother has blood group AB"], "answer": 0, "explanation": "Anti-Rh antibodies made by the mother after a first Rh-positive baby cross the placenta in a later pregnancy and destroy the foetus's red cells. An anti-D injection after delivery prevents sensitisation.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-124", "question": "During blood clotting, soluble fibrinogen is converted into insoluble fibrin threads by the enzyme:", "options": ["Pepsin", "Thrombin", "Amylase", "Lipase"], "answer": 1, "explanation": "Prothrombin is activated to thrombin, which turns fibrinogen into a mesh of fibrin that traps blood cells. Vitamin K is needed to make prothrombin.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-125", "question": "A nerve impulse passes from one neuron to the next across a synapse mainly by means of:", "options": ["Direct flow of blood", "Hormones released into the bloodstream", "Chemical neurotransmitters such as acetylcholine", "Movement of bones"], "answer": 2, "explanation": "At most synapses the arriving impulse releases neurotransmitter molecules that cross the tiny gap and trigger a new impulse in the next cell, which is why signals flow in one direction.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-126", "question": "In the human ear, sound vibrations are converted into nerve impulses in the:", "options": ["Ear drum", "Ear ossicles", "Semicircular canals", "Cochlea"], "answer": 3, "explanation": "The eardrum and ossicles pass vibrations to the fluid-filled cochlea, whose hair cells generate impulses for the auditory nerve. The semicircular canals deal with balance.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-127", "question": "Bacteria become resistant to antibiotics mainly because:", "options": ["Random mutations make some bacteria resistant, and antibiotic use kills the others, leaving resistant ones to multiply", "Antibiotics turn bacteria into viruses", "Bacteria learn to avoid the medicine", "Human cells protect bacteria from medicines"], "answer": 0, "explanation": "Antibiotics act as a selection pressure. Overuse and incomplete courses favour resistant strains, which can also share resistance genes through plasmids.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-128", "question": "mRNA vaccines give protection by:", "options": ["Injecting live, weakened viruses", "Delivering messenger RNA that makes the body's cells produce a viral protein, which the immune system learns to recognise", "Permanently changing the person's DNA", "Supplying ready-made antibodies"], "answer": 1, "explanation": "The mRNA is read in the cytoplasm and soon broken down; it does not enter the nucleus or alter DNA. Ready-made antibodies give passive, short-lived immunity instead.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-129", "question": "Which cell organelle is called the “suicide bag” because its enzymes can digest the cell's own parts?", "options": ["Ribosome", "Golgi apparatus", "Lysosome", "Centrosome"], "answer": 2, "explanation": "Lysosomes contain digestive enzymes that break down worn-out organelles and foreign particles; if they burst, they can digest the cell itself.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-130", "question": "Valves that prevent the backflow of blood are found in the:", "options": ["Arteries", "Capillaries", "Alveoli", "Veins"], "answer": 3, "explanation": "Blood in veins is under low pressure, especially in the legs, so valves stop it flowing backwards. Arteries carry blood at high pressure and do not need such valves (apart from those at the heart's exits).", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-biology-131", "question": "How many of these statements about hormones are correct? I. Thyroxine regulates the body's rate of metabolism. II. Antidiuretic hormone (ADH) reduces the volume of urine. III. Adrenaline raises the heart rate. IV. Deficiency of growth hormone in childhood causes gigantism.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. Too little growth hormone in childhood causes dwarfism; too much causes gigantism, so IV is wrong.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-132", "question": "Match the disease with the organ it mainly affects. A. Hepatitis  B. Pneumonia  C. Glaucoma  D. Arthritis; 1. Joints  2. Eye  3. Lungs  4. Liver", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Hepatitis is inflammation of the liver; pneumonia infects the air sacs of the lungs; glaucoma damages the optic nerve, often through raised pressure in the eye; arthritis inflames the joints.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-133", "question": "Assertion (A): People of blood group O are called universal donors. Reason (R): Their red blood cells carry neither A nor B antigens.", "options": ["Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "With no A or B antigens on the donated cells, the recipient's anti-A or anti-B antibodies have nothing to attack, so O red cells can be given across ABO groups (Rh must still match).", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-134", "question": "How many of these statements about digestion are correct? I. Pepsin works best in the acidic medium of the stomach. II. Trypsin works in the alkaline medium of the small intestine. III. Bile helps digest fats by emulsifying them but contains no digestive enzyme. IV. Salivary amylase begins the digestion of proteins in the mouth.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Salivary amylase acts on starch; protein digestion begins in the stomach with pepsin, so IV is wrong.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-135", "question": "Arrange in the order in which light passes through the human eye: 1. Lens  2. Cornea  3. Retina  4. Vitreous humour", "options": ["2-1-4-3", "1-2-4-3", "2-4-1-3", "2-1-3-4"], "answer": 0, "explanation": "Light enters through the cornea, crosses the aqueous humour and pupil, is focused by the lens, passes through the jelly-like vitreous humour and falls on the retina.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-136", "question": "Arrange in the order in which inhaled air passes through them: 1. Trachea  2. Alveoli  3. Larynx  4. Bronchioles", "options": ["1-3-4-2", "3-1-4-2", "3-4-1-2", "3-1-2-4"], "answer": 1, "explanation": "Air goes from the nose and pharynx into the larynx (voice box), down the trachea, into the bronchi and finer bronchioles, and finally into the alveoli, where gas exchange takes place.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-137", "question": "Match the term with its description. A. Antigen  B. Antibody  C. Vaccine  D. Antiserum; 1. Ready-made antibodies giving immediate, passive immunity, such as anti-snake venom  2. A foreign substance that triggers an immune response  3. A protein made by plasma cells that binds a specific antigen  4. A killed or weakened pathogen, or part of it, that induces active immunity", "options": ["A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-2, B-4, C-3, D-1", "A-2, B-3, C-4, D-1"], "answer": 3, "explanation": "Antigens provoke the response and antibodies neutralise them. A vaccine trains the body's own immunity, which lasts; an antiserum lends antibodies for quick but short protection.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-138", "question": "Assertion (A): People living at high altitudes tend to have more red blood cells than people in the plains. Reason (R): Low oxygen levels stimulate the kidneys to release more erythropoietin, which boosts red cell production.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Erythropoietin from the kidneys signals the bone marrow to make more red cells, raising the blood's capacity to carry the scarcer oxygen; this is part of acclimatisation.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-biology-139", "question": "How many of these statements about vitamins are correct? I. Vitamins A, D, E and K are fat-soluble. II. Vitamin B12 contains cobalt. III. Excess intake of fat-soluble vitamins can build up to toxic levels. IV. Vitamin C is fat-soluble and can be stored in the liver for years.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are correct. Vitamin C is water-soluble and excess is lost in urine, so it must be taken regularly; IV is wrong.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-biology-140","question":"A dry raisin placed in plain water swells up, while a fresh grape placed in thick sugar syrup shrinks. Which single idea explains both observations?","options":["Water moves by osmosis across the cell membrane from the side with more water (dilute) to the side with less water (concentrated)","Sugar diffuses into the raisin and out of the grape, carrying water with it","Water moves from the more concentrated solution to the more dilute solution","Water is pumped into or out of the cells by active transport using ATP"],"answer":0,"explanation":"Osmosis moves water from the dilute side to the concentrated side through a selectively permeable membrane: the raisin's cytoplasm is more concentrated than water, the syrup is more concentrated than the grape's cytoplasm.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-141","question":"A red blood cell placed in distilled water swells and bursts, but an onion peel cell placed in distilled water only becomes stiff (turgid). The structure mainly responsible for this difference is the:","options":["Large central vacuole of the plant cell","Rigid cell wall of the plant cell","Selectively permeable cell membrane of the plant cell","Plastids present in the plant cell"],"answer":1,"explanation":"Both cells take in water by osmosis; the plant cell's rigid cellulose wall resists the expansion of the swelling vacuole, so it becomes turgid instead of bursting. The vacuole is what swells, not what resists.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-142","question":"Which pair of cell organelles contain their own DNA and ribosomes, and can therefore make some of their own proteins?","options":["Golgi apparatus and endoplasmic reticulum","Lysosomes and vacuoles","Mitochondria and plastids","Nucleolus and centrioles"],"answer":2,"explanation":"Mitochondria and plastids (such as chloroplasts) have their own DNA and ribosomes; the other organelles depend entirely on the nucleus for their proteins.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-143","question":"In liver cells, the organelle that plays a key role in detoxifying many poisons and drugs, and in making lipids, is the:","options":["Lysosome","Golgi apparatus","Rough endoplasmic reticulum","Smooth endoplasmic reticulum"],"answer":3,"explanation":"The smooth ER makes lipids and, in liver cells, helps detoxify poisons and drugs. Lysosomes digest worn-out cell parts and foreign material; the rough ER makes proteins.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-144","question":"The stalks of leaves and the stems of climbers bend easily without breaking. The plant tissue that gives them this flexibility, with cells thickened mainly at the corners, is:","options":["Sclerenchyma","Parenchyma","Collenchyma","Xylem"],"answer":2,"explanation":"Collenchyma cells are living, elongated and irregularly thickened at the corners, giving mechanical support with flexibility. Sclerenchyma is rigid and lignified, so it gives strength but not flexibility.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-145","question":"The tough fibrous husk of a coconut is made up mainly of:","options":["Sclerenchyma, whose cells are dead with thick lignified walls","Collenchyma, whose cells are living and thickened at the corners","Parenchyma, whose cells are living with thin walls","Chlorenchyma, whose cells contain chloroplasts"],"answer":0,"explanation":"Coconut husk fibres are sclerenchyma: dead cells with walls thickened by lignin, which makes the tissue hard and stiff.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-146","question":"An athlete ruptures the strong cord that attaches the calf muscle to the heel bone. The tissue that is torn is a:","options":["Ligament","Cartilage","Areolar connective tissue","Tendon"],"answer":3,"explanation":"Tendons join muscles to bones (the calf muscle to the heel bone is the Achilles tendon). Ligaments join bone to bone, and cartilage cushions joints.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-147","question":"Which type of muscle is striated (shows light and dark bands) yet works involuntarily and rhythmically throughout life without tiring?","options":["Skeletal muscle of the limbs","Cardiac muscle","Smooth muscle of the intestine","Muscles of the tongue"],"answer":1,"explanation":"Cardiac muscle is striated like skeletal muscle but involuntary like smooth muscle. Limb and tongue muscles are striated but voluntary; gut muscle is involuntary but unstriated.","difficulty":"moderate","source":"RRB Group D · SSC CHSL"},
  {"id":"sci-biology-148","question":"A potted plant with variegated leaves (green and white patches) is kept in sunlight for a day. One leaf is then boiled in alcohol and tested with iodine solution. What will be seen?","options":["The whole leaf turns blue-black because starch moves throughout the leaf","Only the white parts turn blue-black because they store the starch made by the green parts","No part turns blue-black because boiling in alcohol destroys starch","Only the parts that were green turn blue-black"],"answer":3,"explanation":"Starch forms only where chlorophyll was present, so only the formerly green areas give the blue-black iodine test; this shows chlorophyll is needed for photosynthesis. Alcohol removes chlorophyll, not starch.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-149","question":"Before an experiment to show that carbon dioxide is needed for photosynthesis, the potted plant is kept in complete darkness for about two days. The purpose of this step is to:","options":["Use up the starch already present in the leaves","Stop the plant from respiring during the experiment","Make the leaves produce more chlorophyll","Force all the stomata to close so that no gas enters"],"answer":0,"explanation":"Keeping the plant in darkness destarches the leaves, so any starch found later must have been made during the experiment. Respiration continues in the dark; it does not stop.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-150","question":"In a set-up to show that carbon dioxide is essential for photosynthesis, one leaf of a destarched plant is enclosed in a bottle containing potassium hydroxide. After some hours in sunlight this leaf gives a negative starch test, because potassium hydroxide:","options":["Absorbs the oxygen needed by the leaf","Absorbs carbon dioxide from the air inside the bottle","Destroys the chlorophyll in the leaf","Absorbs water vapour and dries out the leaf"],"answer":1,"explanation":"KOH absorbs CO₂, so the enclosed leaf has no carbon dioxide and cannot make starch, while the leaves outside the bottle can.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-151","question":"Stomatal pores open when the guard cells:","options":["Lose water and shrink, pulling away from each other","Take in water and swell, curving apart because of their uneven walls","Receive abscisic acid from the roots","Are surrounded by air rich in carbon dioxide"],"answer":1,"explanation":"When guard cells absorb water and become turgid, their unevenly thickened walls make them bow outwards, opening the pore. Water loss closes the pore, and abscisic acid causes closure during water stress.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-152","question":"Water reaches the top leaves of a 40-metre-tall tree mainly because of:","options":["Root pressure pushing water upwards","Capillary action in the narrow xylem vessels alone","The suction (transpiration pull) created as water evaporates from the leaves","Active pumping of water by the living phloem cells"],"answer":2,"explanation":"Evaporation from leaves pulls a continuous column of water up the xylem; this transpiration pull is the main force in tall trees. Root pressure and capillarity can raise water only a short height.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-153","question":"Which statement correctly contrasts transport in the phloem with transport in the xylem?","options":["Phloem transport uses energy (ATP) and can move food both upwards and downwards","Phloem transport is purely passive and moves materials only upwards","Phloem carries water and minerals while xylem carries food","Phloem transport takes place through dead, hollow cells"],"answer":0,"explanation":"Translocation in the phloem uses ATP and moves sugars from source to sink in either direction. Xylem transport is largely passive, upward, and through dead cells.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-154","question":"A complete ring of bark (including the phloem) is removed from the trunk of a woody plant. After some weeks, the bark just above the ring swells. The best conclusion is that:","options":["Water moves upwards through the phloem","The xylem lies in the bark and has been cut","Food made in the leaves moves downwards through the phloem and collects above the cut","Food moves upwards through the xylem and is stopped by the cut"],"answer":2,"explanation":"Removing the phloem blocks the downward flow of sugars from the leaves, so food piles up just above the ring. The xylem (wood) is untouched, so the leaves still get water.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-155","question":"Dough left with yeast for some hours becomes soft and rises. The main reason is that yeast:","options":["Gives out oxygen through photosynthesis","Produces lactic acid that makes the dough sour and light","Breaks down protein into ammonia gas","Releases carbon dioxide while breaking down sugars anaerobically"],"answer":3,"explanation":"Yeast ferments sugar into ethanol and carbon dioxide; the trapped CO₂ bubbles make the dough rise. Yeast cannot photosynthesise, and lactic acid is the product of anaerobic respiration in muscles and some bacteria.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-156","question":"Aerobic respiration releases far more energy from one molecule of glucose than anaerobic respiration does, because in aerobic respiration:","options":["Pyruvate is completely broken down to carbon dioxide and water in the mitochondria","Glucose is broken down only in the cytoplasm, which is more efficient","Ethanol is formed and then burnt to release extra heat","Oxygen itself is a source of energy for the cell"],"answer":0,"explanation":"Both kinds begin by splitting glucose into pyruvate in the cytoplasm; only with oxygen is pyruvate fully oxidised to CO₂ and water in mitochondria, releasing much more energy. Ethanol and lactic acid still hold unreleased energy.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-157","question":"Fishes have single circulation, while birds and mammals have double circulation. The main advantage of double circulation is that it:","options":["Lets oxygenated and deoxygenated blood mix, so all organs get equal oxygen","Keeps oxygenated and deoxygenated blood separate, giving the high oxygen supply that warm-blooded animals need","Reduces the work of the heart since blood passes through it only once","Allows the lungs to receive oxygenated blood directly from the left ventricle"],"answer":1,"explanation":"In double circulation blood passes the heart twice per circuit and oxygen-rich blood is kept apart from oxygen-poor blood; this efficient supply supports the high energy needs of keeping body temperature constant.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-158","question":"In which of these animals does the heart have three chambers, so that some oxygenated and deoxygenated blood mixes in the single ventricle?","options":["Rohu fish","Crocodile","Frog","Pigeon"],"answer":2,"explanation":"Amphibians such as the frog have two atria and one ventricle. Fishes have two chambers; crocodiles are reptiles with an exceptional four-chambered heart, and birds have four chambers.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-159","question":"In a blood pressure reading of 120/80 mm Hg, the value 120 represents the pressure:","options":["Inside the veins when the atria contract","In the arteries when the ventricles relax","Inside the right ventricle when it contracts","In the arteries when the ventricles contract"],"answer":3,"explanation":"The upper value is the systolic pressure, recorded in the arteries during ventricular contraction; the lower value (80) is the diastolic pressure during ventricular relaxation.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-160","question":"Running a charcoal stove in a closed room can kill sleeping people. The main reason is that carbon monoxide:","options":["Binds to haemoglobin far more firmly than oxygen, so blood cannot carry enough oxygen","Destroys red blood cells and bursts them","Turns into carbon dioxide in the blood and makes it acidic","Blocks the windpipe by irritating its lining"],"answer":0,"explanation":"CO combines with haemoglobin to form a stable carboxyhaemoglobin, about 200 times more readily than oxygen does, so tissues are starved of oxygen even though the red cells are intact.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-161","question":"Glucose is present in the filtrate formed in the glomerulus, yet the urine of a healthy person normally contains no glucose. This is because:","options":["Glucose molecules are too large to pass from the glomerulus into the capsule","Glucose is completely reabsorbed into the blood from the kidney tubule","The kidney cells use up all of the filtered glucose for their own energy","Filtered glucose is converted into urea in the tubule"],"answer":1,"explanation":"Glucose does pass into the filtrate, but the tubule reabsorbs all of it in a healthy person. Glucose appears in urine only when blood sugar is so high that reabsorption cannot keep up, as in uncontrolled diabetes.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-162","question":"In haemodialysis (an artificial kidney), nitrogenous wastes leave the patient's blood mainly by:","options":["Diffusion through a semi-permeable tube into a dialysing fluid that has no such wastes","Active reabsorption of urea by special pumps in the tubing","Filtration of blood through a glomerulus-like knot of capillaries","Centrifuging the blood to separate urea from the cells"],"answer":0,"explanation":"Blood flows through tubing with a semi-permeable lining bathed in dialysing fluid; urea diffuses out down its concentration gradient. There is no reabsorption in the machine, unlike a real nephron.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-163","question":"You touch a hot iron and pull your hand away before you even feel the pain. This happens because:","options":["The cerebellum detects the heat and moves the hand","Sensory nerves connect directly to the arm muscles with no relay","The message is processed in the spinal cord, which triggers the response; the signal reaching the brain comes slightly later","The brain sends the command first, and the feeling of pain is delayed in the skin"],"answer":2,"explanation":"In a reflex arc, the spinal cord connects the sensory neuron to the motor neuron through a relay neuron and triggers the quick response; the information travels on to the brain, which is why pain is felt a moment later.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-164","question":"Damage to which part of the human brain is most likely to be immediately fatal, because it controls heartbeat, breathing and blood pressure?","options":["Cerebrum","Medulla oblongata","Cerebellum","Hypothalamus"],"answer":1,"explanation":"The medulla in the hindbrain controls involuntary vital actions such as heartbeat, breathing and blood pressure. The cerebellum controls balance and posture, and the hypothalamus regulates temperature, hunger and thirst.","difficulty":"hard","source":"RRB NTPC · SSC CGL"},
  {"id":"sci-biology-165","question":"A potted plant placed near a window bends its shoot towards the light. This happens because auxin:","options":["Is destroyed on the shaded side, so the lighted side grows faster","Collects on the lighted side and makes the cells there divide faster","Is made only in the roots and is carried up to the lighted side","Moves to the shaded side and makes the cells there grow longer"],"answer":3,"explanation":"Light causes auxin to collect on the shaded side of the shoot tip; those cells elongate more, so the shoot curves towards the light.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-166","question":"The leaflets of the touch-me-not plant (Mimosa pudica) fold up within seconds when touched. Which statement about this movement is correct?","options":["It is a growth movement caused by uneven auxin distribution","It is phototropism, since the folding depends on light","It is a non-growth movement caused by cells quickly changing their water content","It is caused by nerve impulses travelling through the plant"],"answer":2,"explanation":"The folding is too fast to be growth; specialised cells rapidly lose water and change shape. Plants have no nerves, though electrical-chemical signals pass from cell to cell.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-167","question":"The tendril of a pea plant coils around a support it touches because:","options":["The side of the tendril away from the support grows faster than the side in contact","The side in contact with the support grows faster than the side away from it","Auxin is destroyed on the side away from the support","The tendril loses water and shrinks on the side touching the support"],"answer":0,"explanation":"In this response to touch, the part of the tendril in contact with the support grows less rapidly than the part away from it, so the tendril curls around the support.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-168","question":"A child shows stunted growth, delayed mental development and a puffy face because of a hormone deficiency that started in infancy. The most likely cause is a deficiency of:","options":["Growth hormone, causing pituitary dwarfism","Thyroxine, causing cretinism","Insulin, causing diabetes","Adrenaline, causing low blood pressure"],"answer":1,"explanation":"Lack of thyroxine from infancy causes cretinism, with both stunted body growth and impaired mental development. Growth hormone deficiency causes dwarfism but with normal intelligence.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-169","question":"Excess growth hormone secreted in an adult, after the long bones have stopped growing in length, leads to:","options":["Gigantism, with an abnormally tall body","Acromegaly, with enlarged hands, feet and jaw","Cretinism, with stunted growth","Dwarfism, with short stature"],"answer":1,"explanation":"Once the growth plates have closed, extra growth hormone cannot add height, so bones of the hands, feet and face thicken (acromegaly). Excess before puberty causes gigantism.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-170","question":"A patient is always thirsty and passes very large volumes of pale, dilute urine, but tests show no sugar in the urine. The hormone most likely to be deficient is:","options":["Insulin","Thyroxine","Antidiuretic hormone (vasopressin)","Adrenaline"],"answer":2,"explanation":"ADH makes the kidney tubules reabsorb water; without it, large volumes of dilute urine are passed (diabetes insipidus). Insulin deficiency would also cause thirst and much urine, but with sugar in it.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-171","question":"How many of these statements about excretion in plants are correct? I. Some waste products are stored in the vacuoles of cells. II. Some wastes are stored as resins and gums, especially in old xylem. III. Plants get rid of some wastes by shedding leaves that contain them. IV. Plants excrete urea through their stomata.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Plants store wastes in vacuoles, as resins and gums in old xylem, and lose some through falling leaves; they also release some into the soil. Urea is not excreted through stomata, which exchange gases and water vapour.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-172","question":"In human females, the egg is normally fertilised in the:","options":["Uterus","Ovary","Cervix","Fallopian tube (oviduct)"],"answer":3,"explanation":"The sperm meets the egg in the oviduct; the zygote then divides as it moves down and implants in the wall of the uterus.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-173","question":"Which of the following are functions of the human placenta? I. Passing glucose and oxygen from the mother to the embryo. II. Passing waste products from the embryo to the mother's blood. III. Letting the mother's blood flow directly into the embryo's blood vessels.","options":["I and II only","I only","II and III only","I, II and III"],"answer":0,"explanation":"The placenta provides a large surface for exchange of nutrients, oxygen and wastes between the two bloodstreams, but the mother's and embryo's blood do not mix directly.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-174","question":"New plants grow from buds present in the notches along the margins of the leaves of:","options":["Potato","Ginger","Bryophyllum","Sweet potato"],"answer":2,"explanation":"Bryophyllum leaves bear buds in their marginal notches that grow into new plants. Potato (stem tuber), ginger (rhizome) and sweet potato (root) propagate from other parts.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-175","question":"Botanists classify a potato as a modified stem and not a root, even though it grows underground. The deciding feature is that the potato:","options":["Stores a large amount of starch","Grows below the soil surface","Has no chlorophyll","Has ‘eyes’, which are nodes bearing buds"],"answer":3,"explanation":"Nodes with buds are a feature of stems, and the eyes of a potato sprout into new shoots. Storing starch and growing underground are true of many roots too, such as the sweet potato.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-176","question":"Match the organism with its usual method of asexual reproduction: A. Hydra B. Spirogyra C. Plasmodium D. Rhizopus; 1. Spore formation 2. Multiple fission 3. Budding 4. Fragmentation","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1"],"answer":0,"explanation":"Hydra buds, the filamentous alga Spirogyra breaks into fragments, the malaria parasite Plasmodium divides by multiple fission, and the bread mould Rhizopus forms spores in sporangia.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-177","question":"After fertilisation in a flowering plant:","options":["The ovules become fruits and the ovary becomes the seed","The ovary develops into the fruit and the ovules into seeds","The petals develop into the fruit and the ovary into seeds","The stigma develops into the fruit and the ovules into the embryo"],"answer":1,"explanation":"The fertilised ovule becomes the seed, containing the embryo, while the ovary ripens into the fruit; petals and stigma usually wither and fall.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-178","question":"Two parents both have blood group A, but their first child has blood group O. What is the probability that their next child will also have blood group O?","options":["0, because O cannot arise from two A parents","1/2","1/4","3/4"],"answer":2,"explanation":"An O child (I°I°) shows that both parents must be I^A I°. Crossing I^A I° × I^A I° gives I°I° with probability 1/4 for every child, regardless of earlier births.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-179","question":"In many turtles and crocodiles, whether an egg hatches into a male or a female depends on:","options":["The X and Y chromosomes received from the father","The temperature at which the fertilised egg is incubated","The amount of yolk stored in the egg","The age of the mother at the time of laying"],"answer":1,"explanation":"In some reptiles the incubation temperature of the eggs decides the sex of the offspring; there are no sex chromosomes as in humans.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-180","question":"A man builds very large muscles through years of weight training. His children will not inherit these large muscles because:","options":["Acquired muscles are removed from the body before reproduction","Muscle-building is a dominant trait that skips a generation","The children's muscles are formed only by the mother's genes","Changes in body (non-reproductive) tissues do not change the DNA of the germ cells"],"answer":3,"explanation":"Traits acquired during a lifetime change only body cells; they are not written into the DNA of sperm or eggs, so they are not inherited. This is why Lamarck's idea of inheritance of acquired characters was rejected.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-181","question":"Which of the following pairs are homologous organs, having the same basic structure and origin but possibly different functions?","options":["Forelimb of a frog and flipper of a whale","Wing of a bat and wing of a butterfly","Potato tuber and sweet potato","Eye of an octopus and eye of a human"],"answer":0,"explanation":"Frog forelimbs and whale flippers share the same pattern of vertebrate limb bones. The other pairs do similar jobs but have different structure and origin (analogous organs), e.g. a potato is a stem while a sweet potato is a root.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-182","question":"A pesticide that does not break down enters a lake. After some years its concentration in body tissues is likely to be highest in:","options":["Phytoplankton","Zooplankton","Small fish","Fish-eating birds"],"answer":3,"explanation":"Non-biodegradable chemicals accumulate at each step of the food chain (biological magnification), so the top consumers carry the highest concentration.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-183","question":"If all the decomposers in an ecosystem were suddenly wiped out, the most direct long-term effect would be that:","options":["Energy would start flowing back from consumers to producers","Producers would make more food since fewer organisms compete with them","Dead bodies and wastes would pile up and nutrients would not be returned to the soil","The oxygen content of the air would rise sharply"],"answer":2,"explanation":"Decomposers break down dead matter and return minerals to the soil for producers to reuse; without them nutrient cycling stops. Energy flow is one-way in any case.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-184","question":"In the food chain grass → grasshopper → frog → snake → eagle, the snake is a:","options":["Secondary consumer at the third trophic level","Tertiary consumer at the fourth trophic level","Secondary consumer at the fourth trophic level","Quaternary consumer at the fifth trophic level"],"answer":1,"explanation":"Grass is level 1 (producer), grasshopper level 2 (primary consumer), frog level 3 (secondary consumer) and snake level 4 (tertiary consumer).","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-185","question":"Farmers often grow a crop of pulses between two cereal crops because leguminous plants:","options":["Have root nodules with Rhizobium bacteria that convert atmospheric nitrogen into compounds plants can use","Absorb nitrogen gas from the air directly through their leaves","Release nitrogen into the soil when they photosynthesise","Kill the denitrifying bacteria present in the soil"],"answer":0,"explanation":"Rhizobium living in the root nodules of legumes fixes atmospheric N₂, enriching the soil with nitrogen compounds. Plants cannot use N₂ directly.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-186","question":"Which of these diseases is caused by a protozoan and is commonly spread through food or water contaminated with faeces?","options":["Cholera","Typhoid","Hepatitis A","Amoebic dysentery (amoebiasis)"],"answer":3,"explanation":"Amoebiasis is caused by the protozoan Entamoeba histolytica. Cholera and typhoid are also water-borne but are bacterial, and hepatitis A is viral.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-187","question":"Doctors do not prescribe antibiotics such as penicillin for the common cold because:","options":["The cold virus multiplies too fast for any medicine to work","Antibiotics act on bacterial structures and processes, such as cell-wall formation, that viruses do not have","Antibiotics kill only fungi and protozoans","A cold is caused by an allergy, not by any microbe"],"answer":1,"explanation":"Antibiotics block bacterial pathways, e.g. penicillin blocks bacterial cell-wall formation. Viruses have no cell wall and use the host cell's machinery, so antibiotics cannot stop them.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-188","question":"HIV gradually weakens the body's immune system mainly by destroying:","options":["Red blood cells","Platelets","Helper T-lymphocytes","Cells of the bone marrow that make red cells"],"answer":2,"explanation":"HIV infects and kills helper T-cells, which coordinate the immune response; as their number falls, the body cannot fight even minor infections (AIDS).","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-189","question":"Fresh amla and guava lose much of their value as a source of one vitamin when cut and left exposed or boiled for long. That vitamin is:","options":["Vitamin C","Vitamin A","Vitamin D","Vitamin K"],"answer":0,"explanation":"Vitamin C is water-soluble and easily destroyed by heat and exposure to air, so long cooking and storage of cut fruit lower it. Vitamins A, D and K are fat-soluble and more stable.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-190","question":"Doctors advise anaemic patients to take iron-rich plant foods along with lemon juice or amla. This is because:","options":["Lemon juice contains a large amount of iron","Vitamin C helps the body absorb iron from plant foods","The acid in lemon kills the worms that cause anaemia","Vitamin C is itself a part of the haemoglobin molecule"],"answer":1,"explanation":"Vitamin C improves the absorption of non-haem iron from plant foods in the intestine. Haemoglobin contains iron, not vitamin C.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-191","question":"Bile contains no digestive enzyme, yet a person whose bile flow is blocked digests fats poorly. Bile helps because it:","options":["Converts fats directly into fatty acids and glycerol","Activates pepsin in the stomach","Breaks large fat globules into tiny droplets, giving lipase a much larger surface to act on","Absorbs fats from the intestine into the blood"],"answer":2,"explanation":"Bile salts emulsify fats, so pancreatic and intestinal lipase can work on a far larger surface. The actual chemical breakdown into fatty acids and glycerol is done by lipase.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-192","question":"A herbivore such as a cow has a much longer small intestine than a carnivore such as a tiger because:","options":["Meat takes longer to digest than grass","Herbivores eat more often than carnivores","Herbivores have no stomach and need a longer intestine","The cellulose in plant food takes longer to digest"],"answer":3,"explanation":"Plant food rich in cellulose needs a longer time and a longer gut to digest; meat is easier to digest, so carnivores have shorter small intestines.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-193","question":"The windpipe (trachea) has C-shaped rings of cartilage in its wall. Their main function is to:","options":["Prevent the trachea from collapsing when air pressure inside it falls","Filter dust from the air","Produce sound during speech","Warm and moisten the inhaled air"],"answer":0,"explanation":"The cartilage rings keep the air passage open at all times. Dust is trapped by mucus and hairs, and sound is produced by the vocal cords in the larynx.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-194","question":"During inhalation in humans:","options":["The diaphragm relaxes and becomes dome-shaped, and the chest cavity becomes smaller","The ribs move down and in, raising the pressure in the lungs","The diaphragm contracts and flattens, the ribs move up and out, and the pressure in the lungs falls below the outside air","Air is actively pumped in by the muscles of the lungs"],"answer":2,"explanation":"Contraction of the diaphragm and rib muscles enlarges the chest cavity; the lungs expand, pressure drops and air rushes in. The lungs have no muscles of their own.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-195","question":"Fishes and other aquatic animals breathe much faster than land animals of similar size because:","options":["Water contains much less dissolved oxygen than the same volume of air","Gills need more oxygen than lungs","Aquatic animals have a higher body temperature","Water contains more carbon dioxide, which speeds up breathing"],"answer":0,"explanation":"The amount of oxygen dissolved in water is far lower than in air, so aquatic animals must pass large volumes of water over their gills quickly.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-196","question":"A cell in the human testis divides by meiosis to form sperms. Each sperm carries:","options":["46 chromosomes, including both X and Y","23 chromosomes, including either an X or a Y","23 chromosomes, all of which carry a Y","22 chromosomes and no sex chromosome"],"answer":1,"explanation":"Meiosis halves the number from 46 to 23; each sperm has 22 autosomes plus one sex chromosome, X or Y, in roughly equal numbers.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-197","question":"If gametes were formed by ordinary mitosis instead of meiosis, what would happen over generations of sexually reproducing organisms?","options":["The chromosome number would stay the same in every generation","The chromosome number would halve in every generation","Offspring would show no variation at all","The chromosome number would double in every generation"],"answer":3,"explanation":"Gametes would carry the full set, so fusion would give a zygote with twice the parental number, doubling each generation. Meiosis halves the number so that fertilisation restores it.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-198","question":"Which combination of features places mushrooms in a kingdom separate from green plants?","options":["They are prokaryotic and have no nucleus","They have no chlorophyll, absorb food from dead matter, and their cell walls contain chitin","They have no cell wall and move about to find food","They photosynthesise but have no roots"],"answer":1,"explanation":"Fungi are eukaryotic heterotrophs (saprotrophs) with cell walls made of chitin, while plants make their own food and have cellulose walls.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-199","question":"Which of these organisms is a prokaryote?","options":["Yeast","Amoeba","Nostoc (a blue-green alga)","Chlamydomonas (a green alga)"],"answer":2,"explanation":"Blue-green algae (cyanobacteria) such as Nostoc have no membrane-bound nucleus, so they belong to Monera. Yeast, Amoeba and Chlamydomonas are eukaryotes despite being single-celled.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-200","question":"Which of these animals is NOT a fish, despite its common name?","options":["Seahorse","Starfish","Flying fish","Dogfish"],"answer":1,"explanation":"The starfish is an echinoderm, with spiny skin and a water-vascular system. The seahorse, flying fish and dogfish (a small shark) all have gills and fins and are true fishes.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-201","question":"Which of these mammals lays eggs?","options":["Kangaroo","Bat","Blue whale","Duck-billed platypus"],"answer":3,"explanation":"The platypus (and the spiny anteater) are egg-laying mammals that still feed their young on milk. Kangaroos give birth to tiny young that develop in a pouch.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-202","question":"Bt cotton suffers much less damage from bollworms because:","options":["It carries a gene from the bacterium Bacillus thuringiensis that makes a protein toxic to these insects","It is sprayed with a bacterial pesticide every week","It is a hybrid whose bolls are too hard for insects to bite","Its leaves produce a strong smell that repels insects"],"answer":0,"explanation":"Bt cotton is genetically modified with the Bt gene, so the plant itself makes an insecticidal (Cry) protein; no spraying is needed for these pests.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-203","question":"‘Golden Rice’ was genetically engineered mainly to fight which deficiency in people who depend on rice?","options":["Iron deficiency","Iodine deficiency","Vitamin A deficiency","Protein deficiency"],"answer":2,"explanation":"Golden Rice makes beta-carotene (a precursor of vitamin A) in its grain, which gives it a golden colour; it targets vitamin A deficiency and night blindness.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-204","question":"The first vaccine was developed by using material from cowpox sores to protect people against smallpox. This was done by:","options":["Louis Pasteur","Edward Jenner","Robert Koch","Alexander Fleming"],"answer":1,"explanation":"Edward Jenner showed in 1796 that cowpox protects against smallpox. Pasteur later made vaccines for rabies and anthrax, Koch identified the TB bacterium, and Fleming discovered penicillin.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-205","question":"Which blood vessel normally carries blood with the lowest concentration of urea?","options":["Hepatic vein","Renal artery","Renal vein","Pulmonary vein"],"answer":2,"explanation":"Urea is made in the liver (so the hepatic vein is rich in it) and removed by the kidneys, so blood leaving them in the renal vein has the least urea.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-206","question":"The first heart sound, ‘lub’, is produced mainly by the:","options":["Closing of the atrioventricular (tricuspid and bicuspid) valves as the ventricles begin to contract","Closing of the semilunar valves at the base of the aorta and pulmonary artery","Opening of the atrioventricular valves as the atria contract","Rush of blood into the aorta"],"answer":0,"explanation":"‘Lub’ comes from the closure of the AV valves at the start of ventricular contraction; ‘dub’ comes from the closure of the semilunar valves when the ventricles relax.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-207","question":"Each heartbeat begins as an electrical impulse from a small patch of specialised tissue in the wall of the right atrium, called the natural pacemaker. It is the:","options":["Atrioventricular (AV) node","Sino-atrial (SA) node","Bundle of His","Purkinje fibres"],"answer":1,"explanation":"The SA node starts each beat; the impulse then passes to the AV node, the bundle of His and the Purkinje fibres, which spread it through the ventricles.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-208","question":"On a humid day at 35 °C we feel far more uncomfortable than on a dry day at the same temperature, because:","options":["Humid air contains less oxygen","Sweat glands stop working when the air is humid","Humid air conducts heat into the body faster","Sweat evaporates slowly into moist air, so the body is cooled less"],"answer":3,"explanation":"Sweating cools the body only when sweat evaporates, taking latent heat from the skin; in humid air evaporation is slow, so cooling is poor.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-209","question":"A piece of plain bread chewed for a long time begins to taste sweet. This is because:","options":["Salivary amylase breaks down starch in the bread into sugar","Saliva itself contains sugar","The bread releases the glucose it already contained","The taste buds get tired and start sensing sweetness"],"answer":0,"explanation":"Salivary amylase (ptyalin) digests starch into maltose, a sugar, which we taste as sweet.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-210","question":"The stomach contains strong hydrochloric acid and the protein-digesting enzyme pepsin, yet it does not normally digest its own wall. The main reason is that:","options":["The stomach wall is made of fat, which pepsin cannot digest","A layer of mucus secreted by the stomach lining protects it","Hydrochloric acid stops pepsin from working","Bile from the liver neutralises the acid in the stomach"],"answer":1,"explanation":"Mucus protects the inner lining from the acid and pepsin; if this protection fails, ulcers can form. HCl actually activates pepsin, and bile acts in the small intestine, not the stomach.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-211","question":"Most peptic ulcers in the stomach and duodenum are now known to be linked to infection by:","options":["The fungus Candida","A virus of the hepatitis group","The protozoan Giardia","The bacterium Helicobacter pylori"],"answer":3,"explanation":"Helicobacter pylori infection damages the protective mucus lining; this discovery earned a Nobel Prize in 2005. Excess acid and painkillers make ulcers worse but the bacterium is the leading cause.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-212","question":"After a meal rich in carbohydrates, the extra glucose in the blood is stored in the liver and muscles as the polysaccharide:","options":["Starch","Cellulose","Glycogen","Chitin"],"answer":2,"explanation":"Animals store glucose as glycogen; plants store it as starch, cellulose forms plant cell walls, and chitin forms insect exoskeletons and fungal cell walls.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-213","question":"During a sudden fright, adrenaline is released into the blood. Which of these effects does it produce? I. Faster heartbeat II. More blood diverted to skeletal muscles III. Faster digestion in the stomach IV. Faster breathing","options":["I and II only","I, II and IV only","I, III and IV only","All four"],"answer":1,"explanation":"Adrenaline prepares the body for action: the heart beats faster, breathing quickens and blood is diverted to the muscles, while blood to the digestive system is reduced, slowing digestion.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-214","question":"In iodine deficiency, the thyroid gland swells to form a goitre. Why does lack of iodine make the gland bigger?","options":["Iodine normally shrinks the gland, so without it the gland swells","Undigested iodine salts collect inside the gland","Low thyroxine makes the pituitary release more thyroid-stimulating hormone, which keeps stimulating the thyroid to grow","Lack of iodine causes an infection of the thyroid"],"answer":2,"explanation":"The thyroid cannot make enough thyroxine without iodine; the pituitary responds by secreting more TSH, which stimulates the thyroid to enlarge (feedback control).","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-215","question":"Seeds are placed in water that has been boiled and cooled, with a layer of oil on top. Similar seeds are placed on moist cotton in open air. Only the second set germinates. This shows that germination needs:","options":["Light","Carbon dioxide","Soil","Oxygen (air)"],"answer":3,"explanation":"Boiling removes dissolved air and the oil layer stops it dissolving again, so the seeds get no oxygen for respiration. Both sets had water, so water is not the variable tested.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-216","question":"Maize and grasses are pollinated by wind. Which set of features are their flowers most likely to have?","options":["Large amounts of light, dry pollen and feathery stigmas","Bright, large petals and sweet nectar","Small amounts of heavy, sticky pollen","A strong scent to attract insects"],"answer":0,"explanation":"Wind pollination is chancy, so such flowers make huge amounts of light, dry pollen and have large feathery stigmas to catch it; colour, scent and nectar attract animals and are not needed.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-217","question":"Which of these birth-control methods also gives protection against sexually transmitted infections such as HIV?","options":["Oral contraceptive pills","Copper-T placed in the uterus","Condom","Vasectomy"],"answer":2,"explanation":"Only a barrier method like the condom prevents contact of body fluids. Pills, Copper-T and vasectomy can prevent pregnancy but give no protection against infections.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-218","question":"Mangrove trees growing in salty, waterlogged mud have roots that grow upwards out of the mud, called pneumatophores. Their main function is to:","options":["Absorb salt from sea water","Take in air for the respiration of the underground roots","Anchor the plant against waves","Store food for the plant"],"answer":1,"explanation":"Waterlogged mud has very little oxygen, so these breathing roots, with pores called lenticels, bring air to the submerged root system.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-219","question":"In a cactus, food is made mainly by the:","options":["Spines, which are modified leaves","Roots, which spread widely","Flowers, which are brightly coloured","Green, fleshy stem"],"answer":3,"explanation":"Cactus leaves are reduced to spines to cut water loss, so the green, flattened or fleshy stem carries out photosynthesis and stores water.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-220","question":"Lichens are often absent from trees in industrial cities. This makes them useful indicators of air polluted especially by:","options":["Sulphur dioxide","Carbon dioxide","Oxygen","Nitrogen"],"answer":0,"explanation":"Lichens (an alga or cyanobacterium living with a fungus) absorb substances directly from the air and are very sensitive to sulphur dioxide, so they disappear where SO₂ pollution is high.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-221","question":"Runoff carrying chemical fertilisers enters a pond. A few weeks later, many fish die. The main reason is that:","options":["The fertilisers are directly poisonous to fish","The fertilisers make the water too salty for the fish","Algae multiply rapidly, and when they die their decomposition by bacteria uses up the dissolved oxygen","The algae release carbon dioxide that poisons the fish during the day"],"answer":2,"explanation":"Nitrates and phosphates cause an algal bloom (eutrophication); dead algae are broken down by aerobic decomposers that use up the dissolved oxygen, so fish suffocate.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-222","question":"The idea that all cells arise only from pre-existing cells (‘omnis cellula e cellula’) was proposed by:","options":["Robert Hooke","Matthias Schleiden","Rudolf Virchow","Antonie van Leeuwenhoek"],"answer":2,"explanation":"Virchow (1855) added this idea to the cell theory of Schleiden and Schwann. Hooke named cells from cork in 1665, and Leeuwenhoek first saw free-living cells.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-223","question":"Amoeba takes in food particles by:","options":["Absorbing them through tiny pores in its cell wall","Engulfing them with finger-like extensions of the cell (pseudopodia), forming a food vacuole","Sweeping them into a fixed mouth using cilia","Digesting them outside the body and absorbing the products"],"answer":1,"explanation":"Amoeba has no cell wall and no fixed mouth; its flexible membrane pushes out pseudopodia that surround the food to form a food vacuole. Paramecium uses cilia to sweep food into its oral groove.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-224","question":"Down syndrome, which causes characteristic facial features and learning difficulties, is caused by:","options":["An extra copy of chromosome 21","A missing X chromosome in a female","An extra X chromosome in a male","A recessive gene carried on the X chromosome"],"answer":0,"explanation":"Down syndrome is trisomy 21: three copies of chromosome 21, usually from an error in meiosis. A missing X gives Turner syndrome and XXY gives Klinefelter syndrome.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-225","question":"Identical twins are always of the same sex, while fraternal twins may be a boy and a girl. The reason is that identical twins:","options":["Are born at the same time from the same placenta","Receive the same mixture of genes from the mother only","Are formed from two eggs fertilised by the same sperm","Develop from a single zygote that splits, so they carry the same chromosomes, including the sex chromosomes"],"answer":3,"explanation":"One fertilised egg splitting into two embryos gives twins with identical chromosome sets, so the same XX or XY. Fraternal twins come from two different eggs fertilised by two different sperms.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-226","question":"Dolly, the first mammal to be cloned from a cell taken from an adult body, was a:","options":["Sheep","Cow","Goat","Mouse"],"answer":0,"explanation":"Dolly the sheep was born in 1996 in Scotland, cloned by placing the nucleus of an adult udder cell into an egg cell whose own nucleus had been removed.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-227","question":"Milk is pasteurised by heating it to about 63 °C for 30 minutes (or 72 °C for 15 seconds) and then cooling it quickly. The purpose is to:","options":["Kill every microbe and spore so that the milk never spoils","Kill most disease-causing microbes without greatly changing the taste and nutrients of milk","Remove extra water and increase the fat content","Break down lactose so that the milk becomes easier to digest"],"answer":1,"explanation":"Pasteurisation is mild heating that destroys most pathogens; it does not sterilise, which is why pasteurised milk must still be refrigerated and used within days.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-228","question":"A spoonful of curd added to warm milk turns the milk into curd in a few hours because:","options":["Yeast in the curd converts the milk sugar into alcohol","The curd adds rennin, which digests the milk fat","Lactobacillus bacteria in the curd convert milk sugar (lactose) into lactic acid, which sets the milk protein","The heat of the milk alone makes the protein coagulate"],"answer":2,"explanation":"Lactic acid bacteria multiply in warm milk and ferment lactose to lactic acid; the acid makes the milk protein (casein) coagulate into curd.","difficulty":"hard","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-229","question":"Pickles and jams keep for months without spoiling mainly because:","options":["Salt and sugar react with microbes and dissolve them","High concentrations of salt or sugar draw water out of microbial cells by osmosis, so they cannot grow","Salt and sugar release oxygen that kills anaerobic bacteria","Salt and sugar make the food too alkaline for microbes"],"answer":1,"explanation":"In a strong salt or sugar solution any microbe loses water by osmosis and becomes dehydrated, so it cannot multiply.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-230","question":"Certain bacteria in waterlogged soil convert nitrates back into free nitrogen gas, which returns to the air. This process is called:","options":["Nitrification","Nitrogen fixation","Ammonification","Denitrification"],"answer":3,"explanation":"Denitrification returns N₂ to the atmosphere. Nitrogen fixation turns N₂ into compounds, ammonification releases ammonia from dead matter, and nitrification turns ammonia into nitrites and nitrates.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-231","question":"A person with blood group B has:","options":["B antigens on the red cells and anti-A antibodies in the plasma","A antigens on the red cells and anti-B antibodies in the plasma","B antigens on the red cells and anti-B antibodies in the plasma","No antigens on the red cells and both anti-A and anti-B antibodies"],"answer":0,"explanation":"Blood group is named after the antigen on the red cells; the plasma carries antibodies against the antigen the person does not have. Having anti-B with B antigen would make one's own blood clump.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-232","question":"A person who steps on a rusty nail is given an anti-tetanus injection. Tetanus is actually caused by:","options":["Iron oxide (rust) entering the bloodstream","A virus that lives on metal surfaces","A fungus that grows on rusted iron","A bacterium whose spores live in soil, dust and animal dung"],"answer":3,"explanation":"Tetanus is caused by the bacterium Clostridium tetani, whose spores enter deep wounds; rusty objects are risky only because they are often dirty and make deep punctures, not because of rust itself.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-233","question":"The Widal test is a blood test commonly used to help diagnose:","options":["Malaria","Typhoid","Tuberculosis","Dengue"],"answer":1,"explanation":"The Widal test detects antibodies against Salmonella typhi, the bacterium that causes typhoid. Malaria is diagnosed by examining a blood smear for the parasite.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-234","question":"Leprosy, a disease that damages the skin and nerves, is caused by a:","options":["Virus","Fungus","Bacterium","Protozoan"],"answer":2,"explanation":"Leprosy is caused by the bacterium Mycobacterium leprae and is curable with multi-drug therapy (a combination of antibiotics).","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-235","question":"Elephantiasis (filariasis), which causes great swelling of the legs, is caused by ___ and spread by the ___ mosquito.","options":["A virus; Aedes","A protozoan; Anopheles","A bacterium; housefly","A roundworm; Culex"],"answer":3,"explanation":"Filariasis is caused by the thread-like roundworm Wuchereria, which blocks lymph vessels, and is spread by Culex mosquitoes. Aedes spreads dengue and Anopheles spreads malaria.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-236","question":"Kala-azar, which causes fever and an enlarged spleen and is found in parts of Bihar and Jharkhand, is spread by the bite of the:","options":["Sandfly","Tsetse fly","Housefly","Culex mosquito"],"answer":0,"explanation":"Kala-azar is caused by the protozoan Leishmania and spread by sandflies. The tsetse fly spreads sleeping sickness, another protozoan disease.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-237","question":"A child with severe diarrhoea is given oral rehydration solution (ORS). Its main purpose is to:","options":["Kill the bacteria causing the diarrhoea","Replace the water and salts lost from the body","Provide proteins to repair the intestine","Stop the intestines from moving"],"answer":1,"explanation":"The main danger in diarrhoea and cholera is dehydration; ORS (water, salts and a little sugar) replaces lost water and electrolytes. It does not kill microbes.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-238","question":"Roughage (dietary fibre) is an important part of a balanced diet even though humans cannot digest it. Its main benefit is that it:","options":["Is the body's main source of energy","Provides the amino acids needed for growth","Adds bulk to food, helping the intestine move it along and preventing constipation","Supplies the vitamins needed to fight infection"],"answer":2,"explanation":"Fibre such as cellulose is not digested in humans but holds water and adds bulk, which helps bowel movement.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-239","question":"Gram for gram, which nutrient gives the body the most energy when fully oxidised?","options":["Fats","Carbohydrates","Proteins","Vitamins"],"answer":0,"explanation":"Fats give about 9 kcal per gram, more than twice the roughly 4 kcal per gram of carbohydrates and proteins. Carbohydrates are the main and quickest source, not the richest; vitamins give no energy.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-240","question":"Match the organism with its mode of nutrition: A. Cuscuta (amarbel) B. Mushroom C. Lichen D. Pitcher plant; 1. Saprotrophic 2. Parasitic 3. Symbiotic 4. Insectivorous (also photosynthetic)","options":["A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4"],"answer":3,"explanation":"Cuscuta is a leafless parasite on host plants, mushrooms feed on dead matter, a lichen is an alga and a fungus living together, and the green pitcher plant traps insects for extra nitrogen.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-241","question":"Assertion (A): Mature human red blood cells cannot carry out aerobic respiration. Reason (R): Mature human red blood cells have no mitochondria.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Mature RBCs lose their nucleus and mitochondria, so they make ATP only by anaerobic breakdown of glucose; this also means they do not use up the oxygen they carry.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-242","question":"Which of these statements about viruses are correct? I. They show signs of life only inside a living host cell. II. They can be grown on a nutrient medium in a dish, like bacteria. III. Some, such as tobacco mosaic virus, can be crystallised. IV. They contain either DNA or RNA as genetic material.","options":["I, III and IV only","I and II only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Viruses multiply only inside living cells, so they cannot be grown on a nutrient medium like bacteria; outside a host they can even be crystallised. Each virus has DNA or RNA, not both.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-243","question":"How many of these statements about sex determination in humans are correct? I. Every egg carries an X chromosome. II. About half of all sperms carry a Y chromosome. III. The mother's egg decides whether the child will be a boy or a girl. IV. A child who receives an X chromosome from the father will be a girl.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements I, II and IV are correct. Since every egg carries X, it is the sperm (X or Y) that decides the sex of the child, so III is wrong.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-biology-244","question":"A pure tall pea plant (TT) is crossed with a pure dwarf plant (tt), and the F₁ plants are self-pollinated. Among the tall plants of the F₂ generation, what fraction will breed true (give only tall plants) on self-pollination?","options":["1/4","3/4","1/2","1/3"],"answer":3,"explanation":"F₂ is 1 TT : 2 Tt : 1 tt, so among the three tall plants only one (TT) is pure-breeding: 1/3. The trap 1/4 is the fraction of TT among all F₂ plants, not among the tall ones.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-245","question":"A person's daytime vision is normal, but he can hardly see in dim light. A deficiency of which vitamin is most likely?","options":["Vitamin B1","Vitamin A","Vitamin D","Vitamin E"],"answer":1,"explanation":"Rod cells of the retina, used in dim light, need a pigment made from vitamin A; its lack causes night blindness. B1 deficiency causes beriberi and D deficiency causes rickets.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-biology-246","question":"In a neuron, a nerve impulse normally travels in which direction?","options":["Axon → cell body → dendrites → nerve ending","Cell body → dendrites → axon → nerve ending","Nerve ending → axon → cell body → dendrites","Dendrites → cell body → axon → nerve ending"],"answer":3,"explanation":"Dendrites pick up the signal, it passes through the cell body and along the axon to its endings, where chemicals are released to cross the synapse to the next cell.","difficulty":"hard","source":"SSC CGL · RRB Group D"},
  {"id":"sci-biology-247","question":"A person who has drunk too much alcohol walks unsteadily and cannot keep his balance. This is mainly because alcohol affects the:","options":["Medulla oblongata","Hypothalamus","Cerebellum","Pituitary gland"],"answer":2,"explanation":"The cerebellum coordinates muscle movements and maintains posture and balance, so its impairment causes staggering. The medulla controls heartbeat and breathing.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-biology-248","question":"Which structure is usually absent from the cells of flowering plants but present in animal cells?","options":["Centrioles","Mitochondria","Golgi apparatus","Endoplasmic reticulum"],"answer":0,"explanation":"Animal cells have a pair of centrioles that help in cell division; cells of higher plants generally lack them. Mitochondria, Golgi bodies and ER occur in both.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-249","question":"Which of these cell structures is found in both a bacterial cell and a human cell?","options":["Mitochondria","Nucleus bounded by a membrane","Endoplasmic reticulum","Ribosomes"],"answer":3,"explanation":"All living cells need ribosomes to make proteins. Bacteria are prokaryotes, lacking a membrane-bound nucleus and membrane-bound organelles like mitochondria and ER.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-biology-250","question":"When a Planaria is cut into several pieces, each piece grows into a complete animal. This ability is called:","options":["Regeneration","Fragmentation","Budding","Binary fission"],"answer":0,"explanation":"Regeneration rebuilds a whole organism from a body part using specialised cells. Fragmentation, as in Spirogyra, is the natural breaking of the body as a regular means of reproduction.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
];

